	edges := make([][]int, len(remaining))
	for k, i := range remaining {
		for _, ref := range deps[i] {
			if j, ok := remIndex[index[ref]]; ok {
				edges[k] = append(edges[k], j)
				reaches[k][j] = true
			}
		}
	}
	// Transitive closure (the induced subgraph is small relative to the
	// document; Floyd-Warshall keeps the cycle-membership test exact).
	for k := range remaining {
		for i := range remaining {
			if !reaches[i][k] {
				continue
			}
			for j := range reaches[k] {
				reaches[i][j] = true
			}
		}
	}

	var cyclic []string
	for k, i := range remaining {
		if reaches[k][k] {
			cyclic = append(cyclic, addresses[i])
		}
	}
