// intHeap is a min-heap of node indices ordered by node address.
type intHeap struct {
	nodes     []int
	addresses []string
}

func newIntHeap() *intHeap {
	return &intHeap{}
}

func (h *intHeap) Len() int { return len(h.nodes) }

func (h *intHeap) Push(i int) {
	h.nodes = append(h.nodes, i)
	h.up(len(h.nodes) - 1)
}

// PopMin removes and returns the index with the smallest address.
func (h *intHeap) PopMin(addresses []string) int {
	h.addresses = addresses
	n := len(h.nodes)
	root := h.nodes[0]
	h.nodes[0] = h.nodes[n-1]
	h.nodes = h.nodes[:n-1]
	if n > 1 {
		h.down(0)
	}
	return root
}

func (h *intHeap) less(i, j int) bool {
	return h.addresses[h.nodes[i]] < h.addresses[h.nodes[j]]
}

func (h *intHeap) swap(i, j int) {
	h.nodes[i], h.nodes[j] = h.nodes[j], h.nodes[i]
}

func (h *intHeap) up(k int) {
	for k > 0 {
		parent := (k - 1) / 2
		if !h.less(k, parent) {
			break
		}
		h.swap(k, parent)
		k = parent
	}
}

func (h *intHeap) down(k int) {
	n := len(h.nodes)
	for {
		left := 2*k + 1
		if left >= n {
			break
		}
		smallest := left
		if right := left + 1; right < n && h.less(right, left) {
			smallest = right
		}
		if !h.less(smallest, k) {
			break
		}
		h.swap(k, smallest)
		k = smallest
	}
